import{_ as a,H as e,f as t,i as r}from"./chunks/framework.Cvt1eIE0.js";const c=JSON.parse('{"title":"第九章 最後の結晶","description":"","frontmatter":{},"headers":[],"relativePath":"story/3-3.md","filePath":"story/3-3.md"}'),o={name:"story/3-3.md"};function s(i,p,n,h,l,d){return e(),t("div",null,[...p[0]||(p[0]=[r('<h1 id="第九章-最後の結晶" tabindex="-1">第九章 最後の結晶 <a class="header-anchor" href="#第九章-最後の結晶" aria-label="Permalink to &quot;第九章 最後の結晶&quot;">​</a></h1><p>エンドの最果て。</p><p>漆黒の大地が、どこまでも広がっていた。</p><p>紫色の空。</p><p>そこに、まるで他のすべてを拒むように、最後のエンドクリスタルが、静かに浮かんでいた。</p><p>その下に立つ男。</p><p>第一竜将。</p><p>SHADOW。</p><p>「……。」</p><p>彼は、静かに大剣を下ろした。</p><p>「皇帝陛下。」</p><p>「申し訳ありません。」</p><p>「私は。」</p><p>「最後まで、間違え続けました。」</p><p>オーレックスは、剣を構えたまま、ゆっくりと近付いた。</p><p>怒りは、まだ消えていなかった。だが、それ以上に、何か別の感情が、彼の中にあった。</p><p>「SHADOW。」</p><p>「もう、戦う必要はない。」</p><p>「……。」</p><p>「終わらせよう。」</p><p>長い沈黙が、二人の間に落ちた。</p><p>やがて。</p><p>SHADOWは、微笑んだ。数千年ぶりに見せる、本物の笑みだった。</p><p>「黄金王。」</p><p>「あなたは。」</p><p>「陛下が信じた通りの人だ。」</p><p>彼は、最後の結晶を、見上げた。</p><p>「私の役目も。」</p><p>「終わりです。」</p><p>ガァァァン！！</p><p>自らの剣で。</p><p>最後のエンドクリスタルを、破壊した。</p><p>「なっ！？」</p><p>スターリンが、目を見開いた。</p><p>「お前……。」</p><p>「ありがとう。」</p><p>SHADOWは、そう言うと、静かに、その場に崩れ落ちた。</p><p>数千年の戦いが、ようやく、終わりを迎えようとしていた。</p><hr><h1 id="第十章-竜王" tabindex="-1">第十章 竜王 <a class="header-anchor" href="#第十章-竜王" aria-label="Permalink to &quot;第十章 竜王&quot;">​</a></h1><p>ゴォォォォォォ！！</p><p>七つの結晶を失った、エンダードラゴン。</p><p>その咆哮は、怒りと絶望に満ちていた。</p><p>『愚かな者ども！』</p><p>『我は永遠！！』</p><p>『我は終焉！！』</p><p>巨大なブレスが、大地を焼いた。</p><p>空間そのものを引き裂く翼が、紫色の空を切り裂いた。</p><p>世界連合軍は、総攻撃を開始した。</p><p>「撃てぇ！！」</p><p>砲撃。</p><p>矢。</p><p>魔法。</p><p>すべてが、竜王へ降り注いだ。</p><p>しかし。</p><p>倒れない。</p><p>「化け物か！」</p><p>スターリンが、叫んだ。</p><p>その時。</p><p>ピックバーグが、叫んだ。</p><p>「オーレックス！」</p><p>「今だ！」</p><p>「心臓だ！」</p><p>黄金王は、頷いた。</p><p>「行く！」</p><p>黄金の剣。</p><p>そして。</p><p>王の冠。</p><p>二つが、共鳴した。</p><p>黄金の光。</p><p>それは。</p><p>初めて冠を手にした、あの日と同じ光だった。</p><p>『力によって支配するな。』</p><p>『知恵によって導け。』</p><p>『民を守る者こそ、王となる。』</p><p>声が、頭の中に、確かに響いた。長い旅の果てで聞いた、あの声と、同じ声だった。</p><p>「うおおおおお！！」</p><p>ズドォォォン！！</p><p>黄金の剣は、エンダードラゴンの胸を、貫いた。</p><p>静寂。</p><p>そして。</p><p>巨大な身体は、無数の光となって、消えていった。</p><p>世界を包んでいた紫色の空が、ゆっくりと、晴れていった。</p><p>戦いは、終わった。</p><p>ついに。</p><p>本当に。</p><p>終わった。</p><hr><h1 id="第十一章-皇帝の国葬" tabindex="-1">第十一章 皇帝の国葬 <a class="header-anchor" href="#第十一章-皇帝の国葬" aria-label="Permalink to &quot;第十一章 皇帝の国葬&quot;">​</a></h1><p>エンド帝国。</p><p>王都。</p><p>数千万の民が、棺の前に集まっていた。</p><p>誰もが、涙を流していた。</p><p>棺の前に立つ、オーレックス。</p><p>「彼は。」</p><p>「偉大な王だった。」</p><p>「そして。」</p><p>「僕の友人だった。」</p><p>短い言葉だった。だが、それ以上の言葉は、見つからなかった。</p><p>スターリンは、静かに、帽子を取った。</p><p>ピックバーグも、涙をぬぐった。眼鏡の奥の目を、何度も。</p><p>そして。</p><p>SHADOW。</p><p>かつて第一竜将と呼ばれた男。</p><p>彼もまた、墓前に、花を供えた。</p><p>「陛下。」</p><p>「おやすみなさい。」</p><p>その短い言葉に、数千年分の後悔と、そして、ようやく訪れた安らぎが、込められていた。</p><p>その日。</p><p>PIGLIN KINGDOMとエンド帝国は、永遠の友好を誓った。</p><p>数千年の対立の歴史に、初めて、終止符が打たれた日だった。</p><hr><h1 id="終章" tabindex="-1">終章 <a class="header-anchor" href="#終章" aria-label="Permalink to &quot;終章&quot;">​</a></h1><p>王国歴十四年。</p><p>黒曜石戦争。</p><p>そして。</p><p>エンダードラゴン戦争。</p><p>二つの大戦争を乗り越えた世界には、ようやく、本当の平和が訪れていた。</p><p>王都 GOLDEN BASTION。</p><p>市場には、笑顔が戻り。</p><p>子供たちは、戦争を知らずに走り回り。</p><p>兵士たちは、安心して眠れるようになった。</p><p>「平和ってのは。」</p><p>「退屈だな。」</p><p>スターリンは、笑った。</p><p>「いいことじゃないか。」</p><p>ピックバーグも、微笑んだ。</p><p>バルコニー。</p><p>夕焼け。</p><p>KING PIGLIN I。</p><p>Aurex Goldtuskは、穏やかな風を、頬に感じていた。</p><p>「これで。」</p><p>「ようやく。」</p><p>「普通の日々が、戻ってくる。」</p><p>彼は、まだ知らなかった。</p><p>この後、王宮の庭園で開かれる、ささやかなお茶会のことを。</p><p>王と兵士が入れ替わる、とんでもない一日のことを。</p><p>そして。</p><p>一人の少女との、運命の出会いのことを。</p><p>それらは、世界を揺るがす戦争などとは無縁の。</p><p>小さくて、少し不思議で、温かい物語。</p><p>英雄たちにも、穏やかな日々は訪れる。</p><p>そして。</p><p>新たな物語は、笑顔と紅茶の香りと共に、始まる。</p><hr><p>PIGLIN KING</p><p>第三巻 エンダードラゴン戦争</p><p>完</p>',148)])])}const u=a(o,[["render",s]]);export{c as __pageData,u as default};
